OWH={}; local os_=GameTooltip.Show; local oh=GameTooltip.Hide; local function tb() local t="?"; if debug and debug.traceback then t=debug.traceback() end; local s=string.gsub(t,"[\r\n]+"," | "); return s end; GameTooltip.Show=function(self) DEFAULT_CHAT_FRAME:AddMessage("GT.SHOW "..string.sub(tb(),1,220)) return os_(self) end; GameTooltip.Hide=function(self) DEFAULT_CHAT_FRAME:AddMessage("GT.HIDE "..string.sub(tb(),1,220)) return oh(self) end; DEFAULT_CHAT_FRAME:AddMessage("HOOKS-OK")